def test_pbt(fn):
    @given(
        test_cases=st.lists(
            st.tuples(
                st.integers(min_value=3, max_value=100),
                st.data()
            ),
            min_size=1,
            max_size=20
        )
    )
    @settings(max_examples=50)
    def _test(test_cases):
        # Build test cases ensuring sum of n <= 5000
        actual_test_cases = []
        total_n = 0
        for n, data in test_cases:
            if total_n + n > 5000:
                break
            arr = data.draw(st.lists(st.integers(min_value=1, max_value=n), min_size=n, max_size=n))
            actual_test_cases.append((n, arr))
            total_n += n

        assume(len(actual_test_cases) > 0)

        # Build input string
        input_lines = [str(len(actual_test_cases))]
        for n, arr in actual_test_cases:
            input_lines.append(str(n))
            input_lines.append(' '.join(map(str, arr)))
        input_str = '\n'.join(input_lines)

        result = fn(input_str).strip()

        # Property 1: Output should have exactly t lines
        output_lines = result.split('\n')
        assert len(output_lines) == len(actual_test_cases), f"Expected {len(actual_test_cases)} lines, got {len(output_lines)}"

        # Property 2: Each line should be either "YES" or "NO"
        for line in output_lines:
            assert line in ["YES", "NO"], f"Invalid output line: {line}"

        # Property 3: Verify against the logic - if any two same elements are at distance >= 2, answer is YES
        for i, (n, arr) in enumerate(actual_test_cases):
            has_palindrome = False
            for j in range(len(arr)):
                for k in range(j + 2, len(arr)):
                    if arr[j] == arr[k]:
                        has_palindrome = True
                        break
                if has_palindrome:
                    break

            expected = "YES" if has_palindrome else "NO"
            assert output_lines[i] == expected, f"Test case {i}: array {arr} should return {expected}, got {output_lines[i]}"

        # Property 4: If all elements are distinct, answer must be NO
        for i, (n, arr) in enumerate(actual_test_cases):
            if len(set(arr)) == len(arr):  # All distinct
                assert output_lines[i] == "NO", f"All distinct elements should give NO, got {output_lines[i]}"

        # Property 5: If there's any duplicate element, answer must be YES
        for i, (n, arr) in enumerate(actual_test_cases):
            if len(set(arr)) < len(arr):  # Has duplicates
                # Check if duplicates are at distance >= 2
                positions = {}
                has_far_duplicate = False
