from hypothesis import given, settings, assume
from hypothesis import strategies as st

def test_pbt(fn):
    @given(
        n=st.integers(min_value=1, max_value=100),
        k=st.integers(min_value=1, max_value=100),
        s=st.text(alphabet=st.characters(min_codepoint=ord('a'), max_codepoint=ord('z')), min_size=1, max_size=100)
    )
    @settings(max_examples=50)
    def _test(n, k, s):
        # Ensure s has exactly n characters
        if len(s) != n:
            s = s[:n] if len(s) > n else s + 'a' * (n - len(s))

        input_str = f"{n} {k}\n{s}"
        result = fn(input_str).strip()

        # Property 1: Output is a single integer (possibly -1)
        assert result.lstrip('-').isdigit(), f"Output must be an integer, got: {result}"
        cost = int(result)

        # Property 2: If output is not -1, it must be non-negative
        if cost != -1:
            assert cost >= 0, f"Cost must be non-negative when not -1, got: {cost}"

        # Property 3: Maximum possible number of distinct subsequences is 2^n
        # So if k > 2^n, the answer must be -1
        max_subsequences = 2 ** n
        if k > max_subsequences:
            assert cost == -1, f"When k={k} > 2^{n}={max_subsequences}, answer must be -1"

        # Property 4: If k=1, cost should be 0 (we can always get the full string at cost 0)
        if k == 1:
            assert cost == 0, f"When k=1, cost should be 0, got: {cost}"

        # Property 5: Upper bound on cost - maximum cost per subsequence is n (delete all characters)
        # So total cost should be at most n * k
        if cost != -1:
            assert cost <= n * k, f"Cost {cost} exceeds theoretical maximum {n * k}"

        # Property 6: If all characters are the same, max subsequences is n+1
        if len(set(s)) == 1:
            if k > n + 1:
                assert cost == -1, f"String of identical chars has only {n+1} subsequences, k={k} should give -1"

    _test()

