        )
    )
    @settings(max_examples=50)
    def _test(t, test_cases):
        test_cases = test_cases[:t]
        lines = [str(len(test_cases))]

        for n, m, tiles in test_cases:
            tiles = tiles[:n]
            n = len(tiles)
            lines.append(f"{n} {m}")
            for a, b, c, d in tiles:
                lines.append(f"{a} {b}")
                lines.append(f"{c} {d}")

