from hypothesis import strategies as st

def test_pbt(fn):
    @given(
        n=st.integers(min_value=1, max_value=50),
        s=st.text(alphabet='abcdefghijklmnopqrstuvwxyz', min_size=1, max_size=50),
        t=st.text(alphabet='abcdefghijklmnopqrstuvwxyz', min_size=1, max_size=50)
    )
    @settings(max_examples=50)
    def _test(n, s, t):
        # Make s and t have length n
        s = s[:n] if len(s) >= n else s + 'a' * (n - len(s))
        t = t[:n] if len(t) >= n else t + 'a' * (n - len(t))

        input_str = f"{n}\n{s}\n{t}"
        result = fn(input_str).strip()

        lines = result.split('\n')

        # Property 1: Output has at least 1 line (the number of moves)
        assert len(lines) >= 1, "Output must have at least one line"

        # Property 2: First line is a valid integer
        try:
            k = int(lines[0])
        except ValueError:
            assert False, "First line must be an integer"

        # Property 3: If k is -1, it means impossible (sorted s != sorted t)
        if k == -1:
            assert sorted(s) != sorted(t), "If output is -1, sorted strings must differ"
        else:
            # Property 4: k must be between 0 and 10000
            assert 0 <= k <= 10000, f"Number of moves must be between 0 and 10000, got {k}"

            # Property 5: If k > 0, there should be a second line with k integers
            if k > 0:
                assert len(lines) >= 2, "If k > 0, there must be a second line with moves"
                moves = lines[1].split()
                assert len(moves) == k, f"Second line must contain exactly {k} moves"

                # Property 6: Each move must be a valid integer in range [1, n-1]
                for move_str in moves:
                    try:
                        move = int(move_str)
                        assert 1 <= move < n, f"Each move must be in range [1, {n-1}], got {move}"
                    except ValueError:
                        assert False, f"Each move must be an integer, got {move_str}"

            # Property 7: If sorted strings are equal, output should not be -1
            if sorted(s) == sorted(t):
                assert k != -1, "If sorted strings are equal, solution should exist"

    _test()

